/**
 * Designed slides: a slide drawn from one of the app's designed templates instead of a
 * layout. The design is the template board's slide with its text taken out. What is
 * left, the art, is a trusted app asset in src/deck/designs (generated by
 * scripts/build-templates.mjs); the deck only stores the design's id, like "bakeSale.2",
 * and the text the person or an AI app typed, which is escaped like any other slot.
 *
 * The art is drawn behind the design's text boxes, except `over`, a second layer some
 * designs paint over a few of them. Each text box is one text slot.
 */
import { LAYOUTS, type Slide, type SlotSpec } from './model'
import { wrappedLines } from './layout'

/** A design's art was drawn at 640 by 360 and is scaled up to the 1920 by 1080 slide. */
export const DESIGN_SCALE = 3

export type Purpose = 'School' | 'Work' | 'Events' | 'Personal' | 'Clubs'

export const PURPOSES: Purpose[] = ['School', 'Work', 'Events', 'Personal', 'Clubs']

/** One editable text box on a design, in slide units (1920 by 1080). */
export interface DesignText {
  /** The slot it shows: title for the most prominent text, then text2, text3… */
  name: string
  /** The box before rotation, which turns it about its centre. */
  x: number
  y: number
  w: number
  h: number
  rotate: number
  font: string
  /** The design's size; longer text shrinks from here to fit the box. */
  size: number
  weight: number
  italic: boolean
  colour: string
  opacity: number
  letterSpacing: number
  /** As a multiple of the size. */
  lineHeight: number
  align: 'left' | 'center' | 'right'
  valign: 'top' | 'middle' | 'bottom'
  transform?: 'uppercase' | 'lowercase' | 'capitalize'
  /** nowrap keeps each line whole; pre keeps spaces too. */
  wrap?: 'nowrap' | 'pre'
  /** How far the first line starts in, past something drawn before it. */
  indent?: number
  shadow?: string
  /** A gradient the text is filled with (CSS background-clip: text); colour is its first colour. */
  gradient?: string
  /** Drawn under the design's `over` art, which partly covers it. */
  under?: boolean
  /** The font's average glyph width as a share of the size, measured on the sample. */
  charW: number
  maxChars: number
  /** The text the design shows, which also tells an AI app what the slot is for. */
  sample: string
}

export interface Design {
  id: string
  /** What the slide is for, in the board's words ("Cover", "On the day"). A message: show it through t(). */
  role: string
  bg: string
  /** Absolutely positioned HTML and SVG covering the slide. Trusted: it comes from the app, never from a deck. */
  art: string
  /** Art painted over the text boxes marked `under` (and under the rest), when the design has any. */
  over?: string
  texts: DesignText[]
}

export interface FontUse {
  family: string
  weight: number
  italic: boolean
}

/** A designed template: one board's designs, in order. */
export interface Board {
  id: string
  /** Every font the art and the text boxes use. */
  fonts: FontUse[]
  designs: Design[]
}

/** What the start screen shows before a board is loaded. */
export interface BoardInfo {
  id: string
  name: string
  blurb: string
  purpose: Purpose
  /** The look's name, like "Confetti". */
  look: string
  fonts: string[]
  slides: number
}

/** Finds a loaded design by id. */
export type DesignLookup = (id: string) => Design | undefined

export const noDesigns: DesignLookup = () => undefined

/** A design id: the board, a dot and the slide number. */
export const DESIGN_ID = /^[A-Za-z][\w-]{0,40}\.\d{1,3}$/

/** The board a design belongs to: "bakeSale" for "bakeSale.2". */
export const boardOf = (designId: string) => designId.slice(0, designId.lastIndexOf('.'))

/** The designs a deck uses. */
export function designIds(slides: { layout: string; design?: string }[]): string[] {
  return [...new Set(slides.flatMap((s) => (s.layout === 'design' && s.design ? [s.design] : [])))]
}

/**
 * A design's slots: one text slot per text box, with the sample as a hint. Every one is
 * required, since an empty box leaves a gap in the design.
 */
export function designSpecs(design: Design): SlotSpec[] {
  return design.texts.map((t) => ({ name: t.name, kind: 'text', required: true, maxChars: t.maxChars, hint: t.sample }))
}

/**
 * The slots a slide has: its layout's, or for a designed slide its design's. Every
 * lookup of a slide's slots goes through here. A design this Glance doesn't have gives
 * no specs; such slides keep their text but can't take new slots.
 */
export function slotSpecsOf(slide: Pick<Slide, 'layout' | 'design'>, designs: DesignLookup): SlotSpec[] {
  if (slide.layout === 'design') {
    const d = slide.design ? designs(slide.design) : undefined
    return d ? designSpecs(d) : []
  }
  return LAYOUTS[slide.layout] as SlotSpec[]
}

/** The family's stack, with fallbacks of the same kind for text the font has no glyphs for. */
export function fontStack(family: string): string {
  const fallback: Record<string, string> = {
    Fraunces: "Georgia, 'Times New Roman', serif",
    'DM Serif Display': "Georgia, 'Times New Roman', serif",
    Caveat: "'Comic Sans MS', cursive",
    'Space Grotesk': "'Segoe UI', Arial, sans-serif",
    'Bricolage Grotesque': "'Segoe UI', Arial, sans-serif",
    Urbanist: "'Helvetica Neue', Arial, sans-serif"
  }
  return `'${family}', ${fallback[family] ?? 'sans-serif'}`
}

/**
 * The width of one line of a box's text at `size`, in slide units, letter spacing and
 * text-transform included: measured in the real font where there is one (the browser's
 * layout, or the PDF font). Without it, widths are estimated from the design's charW.
 */
export type MeasureText = (box: DesignText, line: string, size: number) => number

/** How much room `text` takes at `size`: its height in lines, and its widest line or word. */
function measure(t: DesignText, text: string, size: number, m?: MeasureText): { height: number; width: number } {
  const paras = text.split('\n')
  const indent = (i: number) => (i === 0 ? ((t.indent ?? 0) * size) / t.size : 0)
  if (!m) {
    const glyph = size * t.charW
    if (t.wrap) {
      const widest = Math.max(...paras.map((p, i) => p.length * glyph + indent(i)))
      return { height: paras.length * size * t.lineHeight, width: widest }
    }
    // wrappedLines takes a glyph width as a share of the size.
    const lines = wrappedLines(paras, t.w, size, t.indent ?? 0, t.charW)
    return { height: lines * size * t.lineHeight, width: 0 }
  }
  const shown = (s: string) => m(t, shownText(t, s), size)
  if (t.wrap) return { height: paras.length * size * t.lineHeight, width: Math.max(...paras.map((p, i) => shown(p) + indent(i))) }
  // Wrapped at spaces, as the browser does; the widest word says whether a word must break.
  let lines = 0
  let widest = 0
  paras.forEach((p, i) => {
    const words = p.split(/\s+/).filter(Boolean)
    let line = ''
    let room = t.w - indent(i)
    lines++
    for (const word of words) {
      widest = Math.max(widest, shown(word) + (line ? 0 : t.w - room))
      const next = line ? `${line} ${word}` : word
      if (!line || shown(next) <= room + 0.5) line = next
      else {
        lines++
        line = word
        room = t.w
      }
    }
  })
  return { height: lines * size * t.lineHeight, width: widest }
}

/**
 * The size `text` is drawn at: the design's size while it fits, smaller for longer text,
 * down to half (a quarter for text that doesn't wrap). The box is the limit, or the
 * sample's own room if the measure says the sample needs more, so the sample always
 * shows at the design's size.
 */
export function fitDesignText(t: DesignText, text: string, m?: MeasureText): number {
  if (text === t.sample) return t.size
  const own = measure(t, t.sample, t.size, m)
  const h = Math.max(t.h, own.height)
  const w = Math.max(t.w, own.width)
  // Unwrapped text can only get narrower by getting smaller, so it may go further.
  const min = t.size * (t.wrap ? 0.25 : 0.5)
  for (let size = t.size; size > min; size -= Math.max(1, t.size * 0.04)) {
    const r = measure(t, text, size, m)
    if (r.height <= h + 0.5 && r.width <= w + 0.5) return Math.round(size * 10) / 10
  }
  return Math.round(min * 10) / 10
}

/** A text box ready to draw: the design's box, the slot's text and the size it fits at. */
export interface PlacedText {
  box: DesignText
  text: string
  size: number
  /** The slot is empty: the editor shows the sample as a hint, exports leave it out. */
  placeholder: boolean
}

export function placeTexts(slide: Slide, design: Design, m?: MeasureText): PlacedText[] {
  return design.texts.map((box) => {
    const v = slide.slots[box.name]
    const text = v?.kind === 'text' ? v.value : ''
    const placeholder = !text.trim()
    return { box, text, size: placeholder ? box.size : fitDesignText(box, text, m), placeholder }
  })
}

/** The text as drawn, with the box's text-transform applied, for exports that can't apply it. */
export function shownText(box: DesignText, text: string): string {
  switch (box.transform) {
    case 'uppercase':
      return text.toUpperCase()
    case 'lowercase':
      return text.toLowerCase()
    case 'capitalize':
      return text.replace(/(^|\s)(\S)/g, (_, a: string, b: string) => a + b.toUpperCase())
    default:
      return text
  }
}

/** The slots of a design filled with its own samples, as a template starts. */
export function sampleSlots(design: Design, translate: (s: string) => string = (s) => s): Record<string, string> {
  return Object.fromEntries(design.texts.map((t) => [t.name, translate(t.sample)]))
}
